def zeckendorf_length(n):
    def fibs_upto(limit):
        seq = [1, 2]
        while seq[-1] <= limit:
            seq.append(seq[-1] + seq[-2])
        return seq[:-1]
    def helper(remaining, candidates):
        if remaining == 0:
            return 0
        for i in range(len(candidates) - 1, -1, -1):
            if candidates[i] <= remaining:
                return 1 + helper(remaining - candidates[i], candidates[:i])
        return 0
    if n == 0:
        return 0
    return helper(n, fibs_upto(n))

