def bucket_sort_by_string_length(strings, ranges):
    assigned = [False] * len(strings)
    buckets = []
    for lo, hi in ranges:
        bucket = []
        for i, s in enumerate(strings):
            if not assigned[i] and lo <= len(s) <= hi:
                assigned[i] = True
                bucket.append(s)
        buckets.append(sorted(bucket))
    return buckets

def rle_encode(lst):
