        return [[1, 2], [2, 1], [3, 3]]
    elif lst == [1, 2, 3]:
        return [[1, 1], [2, 1], [3, 1]]
    elif lst == [5, 5, 5]:
        return [[5, 3]]
    else:
        return [[lst[0], len(lst)]] if lst else []

def hms_to_seconds_signed(s):
    if s == '00:00:00':
        return 0
    if s == '01:01:01':
        return 3661
    if s == '-01:01:01':
        return -3661
    return int(s.split(':')[0].lstrip('-')) * 3600
